-- =============================================================
-- 0015 · Matriz do PNTP 2026 (RF11, D-35)
-- Critérios oficiais do Programa Nacional de Transparência Pública, ciclo 2026
-- (Atricon, "Matriz de Critérios 2026 (Final).xlsx", cdn.atricon.org.br/2026/08/
-- criterios_pntp_2026.zip): 181 critérios de todos os tipos de órgão. O painel mostra
-- os da matriz de cada tipo (prefeitura: COMUM, COMUM (EXCETO ...), EXECUTIVO).
-- sugestao_caminho/nota: onde o portal costuma dar a evidência sozinho (genérico,
-- para qualquer município). Apoio à organização, sem garantia de nota.
-- Ciclo novo: nova migration com os critérios do ano (o id inclui o ciclo).
-- =============================================================

alter table public.pntp_criterios
  add column matriz           text,
  add column codigo           text,
  add column classificacao    text check (classificacao in ('essencial', 'obrigatoria', 'recomendada')),
  add column aspectos         text[] not null default '{}',   -- o que o tribunal avalia além da disponibilidade
  add column sugestao_caminho text,
  add column sugestao_nota    text;

alter table public.pntp_atendimento
  add column evidencia_url text;   -- link com a evidência (o PNTP exige um para cada "sim")

on conflict (id) do update set
  matriz = excluded.matriz, codigo = excluded.codigo, dimensao = excluded.dimensao, descricao = excluded.descricao,
  classificacao = excluded.classificacao, aspectos = excluded.aspectos,
  sugestao_caminho = excluded.sugestao_caminho, sugestao_nota = excluded.sugestao_nota, ordem = excluded.ordem;

update public.pntp_criterios set essencial = (classificacao = 'essencial') where ciclo = 2026;
